// ── Suite 4: string-hash ──────────────────────────────────────────────────
// Parity with JS `string-ops`: FNV-1a rolling hash on growing byte strings.
fn run_suite_string_hash<F: FnMut(&mut Vec<Value>, &str, &str, &str, u64, f64, u64)>(
    acc: &mut u64,
